import json
import sys
from pathlib import Path

import numpy as np
import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import common  # noqa: E402


@pytest.fixture(scope="module")
def source():
    # vectors.f16.npy is generated by --import-glove and not committed (too large), e.g. in CI.
    if not common.VECTORS_PATH.exists():
        pytest.skip("artifacts/vectors.f16.npy not present; run build_assets.py --import-glove first")
    words, vectors, _, _ = common.load_source()
    return words, vectors


def test_quantized_ranking_tracks_exact_cosine(source):
    words, vectors = source
    q, inv_norm = common.quantize(vectors)
    index = {w: i for i, w in enumerate(words)}
    for word in ("cheese", "ocean", "king"):
        quantized = common.rank_quantized(q, inv_norm, index[word])
        exact = common.rank_exact(vectors, index[word])
        assert quantized[0] == exact[0] == index[word]
        assert len(set(quantized[1:21]) & set(exact[1:21])) >= 18


def test_exact_cosine_matches_definition(source):
    words, vectors = source
    a, b = vectors[words.index("cheese")], vectors[words.index("butter")]
    expected = float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b)))
    unit = vectors / np.linalg.norm(vectors, axis=1, keepdims=True)
    assert unit[words.index("cheese")] @ unit[words.index("butter")] == pytest.approx(expected, abs=1e-5)


def test_quantize_handles_zero_rows():
    q, inv_norm = common.quantize(np.zeros((2, 4), dtype=np.float32))
    assert q.dtype == np.int8 and np.all(q == 0)
    assert np.all(np.isfinite(inv_norm))


def test_select_targets_rules():
    words = ["the", "cheese", "cheeses", "albania", "ass", "zebra", "abc", "extraordinarily"]
    headwords = {"the", "cheese", "cheeses", "ass", "zebra", "abc", "extraordinarily"}
    targets = common.select_targets(words, headwords, {"ass"}, min_rank=1, max_rank=100)
    # "the" is too frequent, "cheeses" is an inflection, "albania" is not a headword,
    # "ass" is blocklisted, "abc"/"extraordinarily" fail the length rule.
    assert targets == ["cheese", "zebra"]


@pytest.mark.parametrize(
    ("word", "root"),
    [("cheeses", "cheese"), ("pies", "pie"), ("cities", "city"), ("bragging", "brag"), ("hoped", "hope")],
)
def test_inflection_roots(word, root):
    assert root in common.inflection_roots(word)


class FakeMorphology:
    """Stands in for WordNet so the vocabulary rules can be tested without downloading it."""

    BASES = {
        "years": [("year", "n")],
        "scanning": [("scan", "v")],
        "building": [("build", "v")],
        "saw": [("see", "v")],
        "held": [("hold", "v")],
        "stripes": [("stripe", "n"), ("strip", "v")],
        "children": [("child", "n")],
        "physics": [("physic", "n")],
        "rioters": [("rioter", "n")],
        "went": [("go", "v")],
        "dining": [("din", "v"), ("dine", "v")],
    }
    COUNTS = {
        "year": 451,
        "years": 26,
        "scan": 20,
        "scanning": 1,
        "build": 200,
        "building": 80,
        "see": 900,
        "saw": 2,
        "hold": 355,
        "held": 2,
        "stripe": 5,
        "stripes": 1,
        "strip": 50,
        "child": 215,
        "children": 1,
        "physic": 1,
        "physics": 11,
        "go": 400,
        "din": 30,
        "dine": 6,
        "dining": 2,  # under 10% of "din" overall, but over 10% of the verb "dine"
    }
    # Counts for one part of speech only: "din" is a common noun but a rare verb.
    POS_COUNTS = {("din", "v"): 1, ("dine", "v"): 6}
    NOUNS = {"year", "scan", "building", "saw", "stripe", "child", "physic", "physics"}

    def bases(self, word):
        return self.BASES.get(word, [])

    def own_count(self, word, pos=None):
        if pos is not None and (word, pos) in self.POS_COUNTS:
            return self.POS_COUNTS[(word, pos)]
        return self.COUNTS.get(word, 1)

    def has_noun_sense(self, word):
        return word in self.NOUNS


SURFACE = [
    "year",
    "years",
    "scan",
    "scanning",
    "build",
    "building",
    "see",
    "saw",
    "hold",
    "held",
    "stripe",
    "stripes",
    "strip",
    "child",
    "children",
    "physic",
    "physics",
    "x1",
    "ab",
]
HEADWORDS = set(SURFACE) - {"children"}


def test_build_vocabulary_merges_inflections_and_keeps_real_words():
    vocab, aliases = common.build_vocabulary(SURFACE, HEADWORDS, FakeMorphology(), required=set())
    # Mainly inflections merge into their base...
    assert aliases["years"] == "year"
    assert aliases["scanning"] == "scan"
    assert aliases["held"] == "hold"
    # ...preferring a noun base (stripes is a stripe, not a strip)...
    assert aliases["stripes"] == "stripe"
    # ...and non-headword forms still alias to their base.
    assert aliases["children"] == "child"
    # Words common in their own right, and irregular noun homographs, stay.
    for word in ("building", "saw", "physics"):
        assert word in vocab and word not in aliases
    # Frequency order is preserved; non-words and too-short words are excluded.
    assert vocab.index("year") < vocab.index("building") < vocab.index("child")
    assert "x1" not in vocab and "ab" not in vocab
    assert set(aliases.values()) <= set(vocab)


def test_build_vocabulary_pulls_in_rarer_bases_and_two_letter_words():
    surface = ["rioters", "went", "do"]
    headwords = {"rioter", "go", "do"}  # neither surface form is itself a headword
    vocab, aliases = common.build_vocabulary(
        surface, headwords, FakeMorphology(), required=set(), in_source={"rioter", "go"}
    )
    assert aliases == {"rioters": "rioter", "went": "go"}
    assert vocab == ["rioter", "go"]  # "do" has no vector in this source, so it is skipped


def test_build_vocabulary_compares_bases_within_their_part_of_speech():
    surface = ["din", "dine", "dining", "dines"]
    vocab, aliases = common.build_vocabulary(surface, {"din", "dine", "dining"}, FakeMorphology(), required=set())
    # "dining" derives from the verb "dine" (not the noun "din") and is common enough to stay itself.
    assert "dining" in vocab and "dining" not in aliases


def test_build_vocabulary_never_merges_proper_nouns():
    class Wales(FakeMorphology):
        BASES = {**FakeMorphology.BASES, "wales": [("wale", "n")]}
        COUNTS = {**FakeMorphology.COUNTS, "wale": 3}

    surface = ["wales", "wale"]
    merged, _ = common.build_vocabulary(surface, {"wales", "wale"}, Wales(), required=set())
    kept, aliases = common.build_vocabulary(surface, {"wales", "wale"}, Wales(), required=set(), never_merge={"wales"})
    assert "wales" not in merged  # without protection it folds into the lookalike "wale"
    assert "wales" in kept and "wales" not in aliases


def test_build_vocabulary_always_keeps_required_words():
    vocab, aliases = common.build_vocabulary(SURFACE, HEADWORDS, FakeMorphology(), required={"years", "zebra"})
    assert "years" in vocab and "years" not in aliases
    assert "zebra" in vocab  # forced in even though it was never seen


def test_built_assets_are_consistent():
    manifest = json.loads((common.OUTPUT_DIR / "manifest.json").read_text(encoding="utf-8"))
    vocab = json.loads((common.OUTPUT_DIR / "vocab.json").read_text(encoding="utf-8"))
    size = (common.OUTPUT_DIR / "embeddings.bin").stat().st_size
    assert manifest["count"] == len(vocab)
    assert size == manifest["count"] * manifest["dim"] + 4 * manifest["count"]
    assert set(manifest["targets"]) <= set(vocab)
    assert len(manifest["targets"]) == len(set(manifest["targets"])) > 1000
    assert manifest["targets"] == common.load_word_list(common.TARGETS_PATH)


def test_built_aliases_point_into_the_vocabulary():
    vocab = set(json.loads((common.OUTPUT_DIR / "vocab.json").read_text(encoding="utf-8")))
    aliases = json.loads((common.OUTPUT_DIR / "aliases.json").read_text(encoding="utf-8"))
    assert aliases and not (set(aliases) & vocab)
    assert set(aliases.values()) <= vocab
